const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100);
const dateLocal=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateTime=t=>{const d=new Date(t);return dateLocal(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');};
const stamp=t=>new Date(t).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
// A YYYY-MM-DD day as "Oct 28"; offset -1 gives the last day before it ("through Oct 27").
const dayLabel=(d,offset=0)=>new Date(dayStart(d)+offset*86400000+3600000).toLocaleDateString('en-US',{month:'short',day:'numeric'});
// Text the client reads stays free of em dashes (stage and step names use them as separators).
const plain=s=>String(s??'').replace(/\s*[—–]\s*/g,': ');
const icon={upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>'};
