 const currentBuildDesign=()=>{const s=api.state;return projectBuildDesign({floorLip:s.floorLip===true,seamlessCorners:s.seamlessCorners,seamlessCornerSide:s.seamlessCornerSide??'both',seamlessPerimeter:s.seamlessPerimeter,height:s.height,angle:Math.round(+s.angle),floor:s.floor,platformShape:s.platformShape,platformAngle:Math.round(+s.platformAngle),platformBack:Math.round(+s.platformBack),platformSide:Math.round(+s.platformSide),platformFront:Math.round(+(s.platformFront??0)),wallColor:s.wallColor,platformColor:s.platformColor,floorColor:s.floorColor});};
 function buildDesignNote(data){const saved=data.design,normalized=d=>{try{return JSON.stringify(projectBuildDesign(d));}catch{return JSON.stringify(d);}},same=saved&&normalized(saved)===JSON.stringify(currentBuildDesign());return `<div class="pj-build-design"><p>${saved?`Build design: ${escape(designLine(saved))}`:'No build design set. Progress uses the default design.'}</p>${same?'':button('use-design',saved?'Use this device\'s design instead':'Use this device\'s design','pj-text')}</div>`;}
 async function takeEarlyTracking(){return await window.__rcEarlyTracking?.('tracker')??null;}
 async function request(path,method='GET',data){const response=await fetch('/api/project/'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(30000)});const result=await response.json();if(!response.ok){const error=Error(result.error||'Could not save. Try again.');error.status=response.status;throw error;}return result;}
 function error(message){const node=dialog.open?dialog.querySelector('[data-dialog-error]'):host.querySelector('[data-project-error]');if(node){node.textContent=message;node.hidden=false;}}
 async function run(fn){try{await fn();}catch(e){error(e.name==='TimeoutError'?'The request timed out. Try again; saved entries will not be duplicated.':e.message);}}
 async function mutate(kind,fn){if(busy)throw Error('Wait for the current save to finish.');busy=true;host.setAttribute('aria-busy','true');host.inert=true;try{const data=structuredClone(get(kind));fn(data);const saved=await request(kind,'PUT',{data,revision:records[kind].revision});records[kind]=saved;if(kind==='tracking')window.dispatchEvent(new CustomEvent('project-tracking-changed',{detail:saved.data}));render();return true;}finally{busy=false;host.removeAttribute('aria-busy');host.inert=false;}}
 function form(title,body,onSave,saveLabel='Save',extra=''){
  dialog.innerHTML=`<form><div class="pj-dialog-head"><h2 id="pj-dialog-title">${title}</h2><button type="button" data-close aria-label="Close dialog">×</button></div>${body}<p class="pj-error" role="alert" data-dialog-error hidden></p><div class="pj-dialog-actions">${extra}<button type="button" data-close>Cancel</button><button class="pj-primary" type="submit">${saveLabel}</button></div></form>`;
  dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dialog.close());
  dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const data=new FormData(e.target),buttons=[...dialog.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await onSave(data);dialog.close();}catch(err){const el=dialog.querySelector('[data-dialog-error]');el.textContent=err.message;el.hidden=false;}finally{buttons.forEach(b=>b.disabled=false);}};
  if(!dialog.open)dialog.showModal();return dialog;
 }
 function confirm(title,body,fn){form(title,`<p>${escape(body)}</p>`,fn,'Remove');}
 async function load(){const kind=selected,sequence=++loadSequence;if(kind!=='pricing'||!access?.unlocked)host.innerHTML='<p class="pj-loading" role="status">Loading project…</p>';try{if(kind==='finance'||kind==='pricing'){const status=await request('access');const result=status.unlocked?await request('finance'):null;if(sequence!==loadSequence||selected!==kind)return;access=status;if(result)records.finance=result;else delete records.finance;}else if(kind==='tracking'){const early=await takeEarlyTracking(),result=early||await request('tracking');if(sequence!==loadSequence||selected!==kind)return;records.tracking=result;window.dispatchEvent(new CustomEvent('project-tracking-changed',{detail:result.data}));}render();}catch(e){if(sequence!==loadSequence||selected!==kind)return;host.innerHTML=`<p class="pj-error" role="alert">${escape(e.message)}</p>${button('refresh','Try again')}`;}}
 // Cost projection and the Pricing breakdown share one PIN session: unlocking either opens both, and Lock closes both.
 // While locked, the Pricing breakdown tab shows the same PIN screen instead of the breakdown.
 const pricingLocked=()=>selected==='pricing'&&!access?.unlocked;
 function layout(){const on=api.state.mode==='pricing',inGuide=api.state.mode==='build'&&guideDialog.open;tabs.hidden=!on;host.hidden=(!on&&!inGuide)||selected==='pricing'&&!pricingLocked();document.body.classList.toggle('project-module',on&&(selected!=='pricing'||pricingLocked()));tabs.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===selected));b.tabIndex=b.dataset.tab===selected?0:-1;});host.setAttribute('aria-labelledby',inGuide?'guide-tracker-title':'project-tab-'+selected);document.body.dataset.projectTab=on?selected:'';window.dispatchEvent(new Event('project-tab-changed'));}
 async function openGuideTracking(){
  if(guideDialog.open)return;
  const step=api.currentGuideStep(),ids=Object.entries(projectGuideGroups(api.state)).filter(([,stages])=>stages.includes(step.stage)).map(([id])=>id);
  selected='tracking';guideDialog.append(host);guideDialog.querySelector('.guide-tracker-context').textContent=step.title||'Current build step';guideDialog.showModal();layout();await load();
  for(const stage of get('tracking')?.stages||[])if(stage.steps.some(t=>ids.includes(t.id)))openStages.add(stage.id);if(get('tracking'))tracking();
 }
 async function select(value){stopProgressMotion();loadSequence++;clearTimeout(clockTimer);selected=value;try{sessionStorage.setItem('rc-project-tab',value);}catch{}layout();await load();if(value==='tracking')refreshPricingFinance(true);}
 // The fixed panel's materials rows open Pricing breakdown at the still-to-buy list or the To return group.
 async function showPricingSection(id){api.showProjectPricing?.();await select('pricing');for(let i=0;i<40;i++){const el=document.getElementById(id);if(el){if(el.tagName==='DETAILS')el.open=true;const sticky=[...document.querySelectorAll('.pj-sticky')].find(x=>x.offsetParent);el.style.scrollMarginTop=Math.round((parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--pj-sticky-top'))||0)+(sticky?sticky.offsetHeight:0)+12)+'px';el.scrollIntoView({block:'start',behavior:'smooth'});(el.tagName==='DETAILS'?el.querySelector('summary'):el).focus({preventScroll:true});return;}await new Promise(r=>setTimeout(r,50));}}
 tabs.onclick=e=>{const b=e.target.closest('[data-tab]');if(b)run(()=>select(b.dataset.tab));};
 tabs.onkeydown=e=>{const all=[...tabs.children],i=all.indexOf(document.activeElement);if(i<0)return;const n=e.key==='ArrowRight'?(i+1)%3:e.key==='ArrowLeft'?(i+2)%3:e.key==='Home'?0:e.key==='End'?2:null;if(n!==null){e.preventDefault();all[n].focus();run(()=>select(all[n].dataset.tab));}};
 const progressButton=document.createElement('button');progressButton.id='viewport-project-progress';progressButton.type='button';progressButton.disabled=true;progressButton.setAttribute('aria-label','Project progress loading');progressButton.innerHTML='<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="32" r="26" class="progress-track"/><circle cx="32" cy="32" r="26" class="progress-value" pathLength="100" stroke-dasharray="0 100"/></svg><span>0<small>%</small></span>';document.querySelector('.viewport').append(progressButton);
 const progressIntro=createProgressIntro({paint:fraction=>{for(const el of document.querySelectorAll('[data-load-percent]'))el.textContent=Math.round(Number(el.dataset.loadPercent)*fraction);for(const el of document.querySelectorAll('[data-load-arc]')){const length=Number(el.dataset.loadArc)*fraction;el.setAttribute('stroke-dasharray',length+' '+el.dataset.loadCirc);el.setAttribute('stroke-linecap',length>0?'round':'butt');}}});
 progressButton.onclick=()=>{if(api.state.mode==='build'){run(openGuideTracking);return;}selected='tracking';try{sessionStorage.setItem('rc-project-tab','tracking');}catch{}api.setMode('pricing');tabs.scrollIntoView({block:'start',behavior:'smooth'});tabs.querySelector('[data-tab="tracking"]').focus({preventScroll:true});};
 let ringTracking=null;
 const paintRing=detail=>{if(!detail)return;ringTracking=detail;const e={detail};const w=progressWeights(buildDesign(e.detail)),p=projectProgress(e.detail,w);progressButton.disabled=false;let offset=0;const colors=['#c7ec9d','#81b7ba','#c3b8e8','#e4c58c'];progressButton.querySelector('svg').innerHTML=e.detail.stages.map((stage,index)=>{const length=projectStageWeight(stage,w)/Math.max(1e-9,p.weight)*100,arc=Math.max(0,length-1.3),done=arc*projectStagePercent(stage,w)/100,color=colors[({walls:0,floor:1,platform:2,'wall-finishing':3,'floor-finishing':1,'platform-finishing':2})[stage.id]??index%4],shape=`cx="32" cy="32" r="26" pathLength="100" transform="rotate(-90 32 32)" stroke="${color}" stroke-dashoffset="${-offset}"`;offset+=length;return `<circle ${shape} stroke-opacity=".2" stroke-dasharray="${arc} 100"/><circle ${shape} data-load-arc="${done}" data-load-circ="100" stroke-linecap="${done?'round':'butt'}" stroke-dasharray="${done} 100"/>`;}).join('');progressButton.querySelector('span').innerHTML=`<em data-load-percent="${p.percent}">0</em><small>%</small>`;progressButton.setAttribute('aria-label','Project '+p.percent+'% complete. Open Project tracking');progressIntro.start();};
 for(const event of ['project-tracking-loaded','project-tracking-changed'])window.addEventListener(event,e=>paintRing(e.detail));
 // Public completion always uses estimated task weights, independent of private finance access.
 window.addEventListener('project-finance-changed',()=>{paintRing(ringTracking);if(selected==='tracking'&&get('tracking')&&!editingProject())tracking();});
 const baseMode=api.setMode;api.setMode=m=>{if(m!=='build'&&guideDialog.open)guideDialog.close();const result=baseMode(m);layout();if(m==='pricing')run(load);return result;};
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>api.setMode(b.dataset.mode));
 window.addEventListener('studio-view-changed',layout);
 // Sticky cost summaries sit below the 3D view when it is pinned to the top (phones), otherwise at the very top.
 const viewport=document.querySelector('.viewport'),stickyTop=()=>{const strip=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--viewport-strip'))||0,tabsPinned=!tabs.hidden&&getComputedStyle(tabs).position==='sticky';document.documentElement.style.setProperty('--pj-sticky-top',Math.round(strip+(tabsPinned?tabs.offsetHeight:0))+'px');};
 new ResizeObserver(stickyTop).observe(viewport);window.addEventListener('resize',stickyTop);window.addEventListener('studio-view-changed',stickyTop);window.addEventListener('project-tab-changed',stickyTop);window.addEventListener('viewport-strip-changed',stickyTop);stickyTop();
 try{const saved=sessionStorage.getItem('rc-project-tab');if(['pricing','finance','tracking'].includes(saved))selected=saved;}catch{}
 function header(){return '<p class="pj-error" data-project-error role="alert" hidden></p>';}
 function renderGate(){host.innerHTML=header()+`<div class="pj-gate"><div class="pj-lock-mark">${svg('lock')}</div><h3>${access?.configured?'Unlock project costs':'Keep project costs private'}</h3><p>${access?.configured?'Enter your four-digit project PIN. It unlocks Cost projection and the Pricing breakdown.':'Create a four-digit PIN for spending, receipts, crew time and the Pricing breakdown.'}</p><form id="pj-pin-form">${field('pin','Project PIN','','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required aria-label="Four-digit project PIN"')}${!access?.configured?field('repeat','Confirm PIN','','password','inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" autocomplete="off" required'):''}<button class="pj-primary" type="submit">${access?.configured?'Unlock costs':'Create PIN'}</button></form></div>`;
 host.querySelector('form').onsubmit=e=>{e.preventDefault();const values=new FormData(e.target);run(async()=>{if(!access.configured&&values.get('pin')!==values.get('repeat'))throw Error('The PINs do not match.');const submit=e.target.querySelector('button');submit.disabled=true;try{await request('access','POST',{action:access.configured?'unlock':'setup',pin:values.get('pin')});await load();}finally{submit.disabled=false;}});};}
 function taskName(id){return NON_BUILD_ACTIVITIES.find(a=>a.id===id)?.name||shoppingNames[id]||api.labor?.().tasks.find(t=>t.id===id)?.name||(id?'Stage not in this design':'No stage assigned');}
 function spendHero(data,p){const lock=button('lock',svg('lock'),'pj-icon pj-spend-lock','aria-label="Lock project costs" title="Lock project costs"');
  if(!p){const budget=api.projectBudget?.(),totals=projectTotals({...data,budgetCents:budget?.totalCents??null}),denom=Math.max(1,totals.total,budget?.totalCents||0),ratio=c=>Math.max(0,Math.min(100,c/denom*100));
   return `<div class="pj-sticky"><div class="pj-spend-hero">${lock}<span class="pj-overline">TOTAL SPENT</span><strong data-total>${usd(totals.total)}</strong><div class="pj-cost-split"><div><i class="pj-dot material"></i><span>Materials</span><b data-materials>${usd(totals.materials)}</b></div><div><i class="pj-dot labor"></i><span>Labor</span><b data-labor>${usd(totals.labor)}</b></div></div><div class="pj-spend-track"><i style="width:${ratio(totals.materials)}%"></i><i style="width:${ratio(totals.labor)}%"></i></div><div class="pj-budget"><span data-remaining>${totals.remaining===null?'Loading pricing guide budget…':`${usd(Math.abs(totals.remaining))} ${totals.remaining<0?'over estimate':'remaining'}`}</span>${button('budget',budget?`of ${usd(budget.totalCents)} ↗`:'View pricing ↗')}</div></div></div>`;}
  const share=c=>Math.max(0,Math.min(100,c/Math.max(1,p.projectedCents)*100));
  // Fixed price to finish: the client total is billed so far + the fixed labor + materials at cost, compared with the
  // total agreed when the fixed price was set. The original quote stays visible underneath.
  // Fixed price: the hero is only the projection. The fixed-cost widget below carries the breakdown.
  if(p.fixed)return `<div class="pj-sticky"><div class="pj-spend-hero pj-hero-compact">${lock}<span class="pj-overline">PROJECTED TOTAL</span><strong data-projected>${usd(p.projectedCents)}</strong><div class="pj-spend-track"><i style="width:${share(p.spentCents)}%"></i><i style="width:${share(p.toGoCents)}%"></i></div><div class="pj-hero-split"><span><i class="pj-dot material"></i>Spent so far <b data-total>${usd(p.spentCents)}</b></span><span><i class="pj-dot labor"></i>Still to come <b data-to-go>${usd(p.toGoCents)}</b></span></div></div></div>`;
  const against=p.varianceCents===0?`On the ${usd(p.baselineCents)} ${p.quoteCents===null?'estimate':'quote'}`:`${usd(Math.abs(p.varianceCents))} ${p.varianceCents>0?'over':'under'} the ${usd(p.baselineCents)} ${p.quoteCents===null?'estimate':'quote'}`;
  return `<div class="pj-sticky"><div class="pj-spend-hero pj-hero-compact">${lock}<span class="pj-overline">PROJECTED TOTAL</span><strong data-projected>${usd(p.projectedCents)}</strong><p class="pj-hero-quote"><span data-remaining>${against}</span>${button('quote',p.quoteCents===null?'Set quote':'Edit quote')}${button('fixed-price','Fixed price','pj-text')}</p><div class="pj-spend-track"><i style="width:${share(p.spentCents)}%"></i><i style="width:${share(p.toGoCents)}%"></i></div><div class="pj-hero-split"><span><i class="pj-dot material"></i>Spent <b data-total>${usd(p.spentCents)}</b></span><span><i class="pj-dot labor"></i>Still to come <b data-to-go>${usd(p.toGoCents)}</b></span></div></div></div>`;}
 // The quote given to the client, stored on the shared finance record so every viewer measures against it.
 function quoteForm(){const current=get('finance').budgetCents,estimate=api.projection?.()?.estimateCents;form('Quoted estimate',field('quote','Quoted total ($)',current===null?'':(current/100).toFixed(2),'number','min="0" max="9999999" step="0.01" inputmode="decimal" placeholder="Blank to compare with the live estimate"')+`<p class="pj-review-note">The total you quoted. The projected total is compared with it. ${estimate!=null?`The current estimate is ${usd(estimate)}.`:''} Leave blank to compare with the live estimate instead.</p>`,async values=>{const raw=String(values.get('quote')).trim(),cents=raw===''?null:Math.round(Number(raw)*100);if(cents!==null&&!(Number.isSafeInteger(cents)&&cents>=0))throw Error('Enter a dollar amount, or leave it blank.');await mutate('finance',d=>{d.budgetCents=cents;});},'Save quote');}
 // Fixed price to finish. Saving records the projected total of that moment as the agreed total.
 function fixedPriceForm(){const current=get('finance').fixedPrice;form('Fixed price to finish',field('start','Fixed price starts on',current?.startDate||dateLocal(),'date','required')+field('labor','Fixed labor to finish ($)',current?(current.laborCents/100).toFixed(2):'','number','min="1" max="9999999" step="0.01" inputmode="decimal" required')+field('rate','Hourly rate it is based on ($/h)',current?(current.rateCents/100).toFixed(2):'','number','min="1" max="99999" step="0.01" inputmode="decimal" required')+noteField(current?.note)+`<p class="pj-review-note">Work before the start date stays time and materials. From then on the client pays this labor flat, plus materials at cost with receipts; shopping trips are off the clock. Saving records today's projected total as the agreed total.${current?.agreedTotalCents!=null?` Agreed so far: ${usd(current.agreedTotalCents)}.`:''}</p>`,async values=>{const cents=name=>Math.round(Number(String(values.get(name)).trim())*100);await api.project.setFixedPrice({startDate:String(values.get('start')),laborCents:cents('labor'),rateCents:cents('rate'),note:String(values.get('note')||'')});},'Save',current?button('clear-fixed','Remove fixed price','pj-text'):'');}
 // The fixed-cost widget, for anyone with the PIN: the fixed labor at its hourly rate, materials bought and refunded
