 let livePending=false,liveGeneration=0;
 async function refreshTracking(){
  if(livePending||document.hidden||selected!=='tracking'||(api.state.mode!=='pricing'&&!guideDialog.open)||busy||dialog.open||dragged||host.querySelector('[data-dirty="true"]')||host.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select'))return;
  livePending=true;const sequence=loadSequence,generation=liveGeneration;
  try{const result=await request('tracking');if(sequence!==loadSequence||generation!==liveGeneration||busy||dialog.open||dragged||host.querySelector('[data-dirty="true"]')||host.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select'))return;
   if(result.revision!==(records.tracking?.revision??-1)){records.tracking=result;window.dispatchEvent(new CustomEvent('project-tracking-changed',{detail:result.data}));tracking();}
   host.querySelector('[data-project-error]')?.setAttribute('hidden','');
  }catch{if(sequence===loadSequence&&selected==='tracking')error('Connection interrupted. Retrying automatically…');}finally{livePending=false;}
 }
 let financePending=false;
 const editingProject=()=>busy||dialog.open||host.contains(document.activeElement)&&document.activeElement.matches('input,textarea,select');
 async function refreshFinance(){
  if(financePending||document.hidden||selected!=='finance'||api.state.mode!=='pricing'||editingProject())return;
  financePending=true;const sequence=loadSequence,previous=records.finance;
  try{
   const nextAccess=await request('access'),result=nextAccess.unlocked?await request('finance'):null;
   if(sequence!==loadSequence||selected!=='finance'||api.state.mode!=='pricing'||editingProject()||records.finance!==previous)return;
   const changed=access?.configured!==nextAccess.configured||access?.unlocked!==nextAccess.unlocked||result?.revision!==previous?.revision;
   access=nextAccess;if(result)records.finance=result;else{delete records.finance;clearTimeout(clockTimer);}
   if(changed)render();host.querySelector('[data-project-error]')?.setAttribute('hidden','');
  }catch(e){if(sequence===loadSequence&&selected==='finance'&&!editingProject()){if(e.status===401){delete records.finance;access={...access,unlocked:false};clearTimeout(clockTimer);render();}else error('Connection interrupted. Retrying automatically…');}}
  finally{financePending=false;}
 }
 // On the Pricing guide tab, keep the projection's finance copy current without the burn-down UI.
 let pricingFinancePending=false,pricingFinanceAt=0;
 async function refreshPricingFinance(force=false){
  if(pricingFinancePending||document.hidden&&!force||!['pricing','tracking'].includes(selected)||api.state.mode!=='pricing'&&!guideDialog.open||busy||!force&&Date.now()-pricingFinanceAt<15000)return;
  pricingFinancePending=true;pricingFinanceAt=Date.now();
  try{const status=await request('access');const result=status.unlocked?await request('finance'):null;if(!['pricing','tracking'].includes(selected)||busy)return;const was=!!access?.unlocked;access=status;if(result){if(result.revision!==records.finance?.revision)records.finance=result;}else delete records.finance;if(was!==!!status.unlocked&&selected==='pricing'&&!editingProject())render();else publishFinance();}
  catch{}finally{pricingFinancePending=false;}
 }
