 function stepForm(stageId,step=null){form(step?'Edit production step':'Add production step',field('name','Step name',step?.name||'','text','required maxlength="160"'),async values=>{await mutate('tracking',d=>{const s=d.stages.find(s=>s.id===stageId),row={id:step?.id||crypto.randomUUID(),name:values.get('name').trim(),percent:step?.percent||0,notes:step?.notes||[]};if(step)s.steps[s.steps.findIndex(t=>t.id===step.id)]=row;else s.steps.push(row);});},'Save',step&&get('tracking').stages.find(s=>s.id===stageId).steps.length>1?button('delete-step','Remove step','pj-danger',`data-id="${step.id}" data-stage-id="${stageId}"`):'');}
